// apply-halaman2.mjs — Bangun halaman: Command Media, Project N219, OC, HKI,
//   Online Publication, dan Our Library (indeks + katalog dinamis).
//   Konsolidasi: satu halaman per menu (accordion/seksi), bukan puluhan route.
// PRASYARAT: jalankan SETELAH apply-dinamis, apply-navbar, apply-navbar-visual,
//            apply-fixes, apply-halaman.
// Cara pakai (dari root project):
//     node apply-halaman2.mjs
//     npm run dev     (WAJIB restart penuh — ada route baru)
// Aman dijalankan berkali-kali.

import { writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const FILES = [
  ["src/lib/server/db/schema.ts", ''],
  ["src/lib/types/content.ts", ''],
  ["src/lib/server/portal/queries.ts", ''],
  ["src/lib/data/nav.ts", ''],
  ["src/lib/config/site.ts", ''],
  ["src/lib/components/layout/site-header.svelte", ''],
  ["src/lib/components/shared/catalog-table.svelte", ''],
  ["src/routes/command-media/+page.server.ts", ''],
  ["src/routes/command-media/+page.svelte", ''],
  ["src/routes/project/+page.server.ts", ''],
  ["src/routes/project/+page.svelte", ''],
  ["src/routes/oc/+page.server.ts", ''],
  ["src/routes/oc/+page.svelte", ''],
  ["src/routes/hki/+page.server.ts", ''],
  ["src/routes/hki/+page.svelte", ''],
  ["src/routes/online-publication/+page.server.ts", ''],
  ["src/routes/online-publication/+page.svelte", ''],
  ["src/routes/library/+page.server.ts", ''],
  ["src/routes/library/+page.svelte", ''],
  ["src/routes/library/[catalog]/+page.server.ts", ''],
  ["src/routes/library/[catalog]/+page.svelte", ''],
];

let ok = 0;
for (const [path, b64] of FILES) {
  try {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, Buffer.from(b64, 'base64'));
    console.log('  ditulis:', path);
    ok++;
  } catch (e) {
    console.error('  GAGAL  :', path, '-', e.message);
  }
}
console.log('\nSelesai. ' + ok + '/' + FILES.length + ' file ditulis.');
console.log('Restart dev server (WAJIB, ada route baru): npm run dev');
console.log('Halaman baru: /command-media /project /oc /hki /online-publication /library');
console.log('Tombol Our Library di header sekarang mengarah ke /library.');
console.log('Sisa "Segera": Regulation (3), Jadwal KA & Penerbangan, Link — tinggal bilang kalau mau dibangun.');
